  1	/**
  2	 * Tests for the Repository Registry API handler layer (WP-006).
  3	 *
  4	 * Coverage:
  5	 *   AC-1: GET /api/repos returns all declared repositories from the registry file.
  6	 *   AC-2: POST /api/repos creates a new repository entry with validated id (slug regex),
  7	 *         unique id, and no folder_names conflicts; returns 400 with clear error on conflict.
  8	 *   AC-3: PUT /api/repos/:repoId updates label, folder_names, and vision fields;
  9	 *         enforces folder_name uniqueness across all entries.
 10	 *   AC-4: DELETE /api/repos/:repoId removes the entry without deleting project data.
 11	 *   AC-5: GET /api/repos/:repoId returns the full repository entry or 404 if not found.
 12	 *   AC-6: Folder names are unique across all entries — create/update rejects conflicts.
 13	 *
 14	 * Uses real temp directories (no registry file pre-created — first-run scenario).
 15	 */
 16	
 17	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 18	import { mkdtemp, rm } from 'fs/promises';
 19	import { join } from 'path';
 20	import { tmpdir } from 'os';
 21	
 22	import {
 23	  handleListRepos,
 24	  handleGetRepo,
 25	  handleCreateRepo,
 26	  handleUpdateRepo,
 27	  handleDeleteRepo,
 28	  ApiError,
 29	} from '../../gui/api-repos.js';
 30	import { loadRegistry } from '../../src/storage/repository-registry.js';
 31	import type { RepositoryEntry } from '../../src/schema/repository-registry.js';
 32	
 33	// ---------------------------------------------------------------------------
 34	// Helpers
 35	// ---------------------------------------------------------------------------
 36	
 37	/** Build a minimal valid create-repo body. */
 38	function makeCreateBody(
 39	  overrides: Partial<{
 40	    id: string;
 41	    label: string;
 42	    folder_names: string[];
 43	    vision: { short_term: string | null; mid_term: string | null; long_term: string | null };
 44	  }> = {}
 45	): {
 46	  id: string;
 47	  label: string;
 48	  folder_names: string[];
 49	  vision?: { short_term: string | null; mid_term: string | null; long_term: string | null };
 50	} {
 51	  return {
 52	    id: 'my-repo',
 53	    label: 'My Repository',
 54	    folder_names: ['my-repo-folder'],
 55	    ...overrides,
 56	  };
 57	}
 58	
 59	// ---------------------------------------------------------------------------
 60	// Suite
 61	// ---------------------------------------------------------------------------
 62	
 63	describe('WP-006 Repository Registry API Handlers', () => {
 64	  let ledgerRoot: string;
 65	
 66	  beforeEach(async () => {
 67	    ledgerRoot = await mkdtemp(join(tmpdir(), 'api-repos-test-'));
 68	  });
 69	
 70	  afterEach(async () => {
 71	    await rm(ledgerRoot, { recursive: true, force: true });
 72	  });
 73	
 74	  // ─── handleListRepos ────────────────────────────────────────────────────
 75	
 76	  describe('handleListRepos (GET /api/repos)', () => {
 77	    // AC-1: empty registry returns empty array
 78	    it('AC-1: returns empty array when no registry file exists', async () => {
 79	      const result = await handleListRepos(ledgerRoot);
 80	      expect(result).toEqual([]);
 81	    });
 82	
 83	    it('AC-1: returns all declared repositories', async () => {
 84	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', label: 'Repo A', folder_names: ['folder-a'] }));
 85	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-b', label: 'Repo B', folder_names: ['folder-b'] }));
 86	
 87	      const result = await handleListRepos(ledgerRoot);
 88	      expect(result).toHaveLength(2);
 89	      const ids = result.map((r) => r.id);
 90	      expect(ids).toContain('repo-a');
 91	      expect(ids).toContain('repo-b');
 92	    });
 93	
 94	    it('AC-1: list items include id, label, folder_names, has_vision, created_at, last_modified', async () => {
 95	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', label: 'Repo A', folder_names: ['fa'] }));
 96	
 97	      const result = await handleListRepos(ledgerRoot);
 98	      expect(result).toHaveLength(1);
 99	      const item = result[0]!;
100	      expect(item).toHaveProperty('id', 'repo-a');

101	      expect(item).toHaveProperty('label', 'Repo A');
102	      expect(item).toHaveProperty('folder_names', ['fa']);
103	      expect(item).toHaveProperty('has_vision', false);
104	      expect(item).toHaveProperty('created_at');
105	      expect(item).toHaveProperty('last_modified');
106	    });
107	
108	    it('has_vision is true when at least one horizon is non-null', async () => {
109	      await handleCreateRepo(
110	        ledgerRoot,
111	        makeCreateBody({
112	          id: 'repo-v',
113	          folder_names: ['fv'],
114	          vision: { short_term: 'Ship fast', mid_term: null, long_term: null },
115	        })
116	      );
117	
118	      const result = await handleListRepos(ledgerRoot);
119	      expect(result[0]!.has_vision).toBe(true);
120	    });
121	
122	    it('has_vision is false when all horizons are null', async () => {
123	      await handleCreateRepo(
124	        ledgerRoot,
125	        makeCreateBody({
126	          id: 'repo-nv',
127	          folder_names: ['fnv'],
128	          vision: { short_term: null, mid_term: null, long_term: null },
129	        })
130	      );
131	
132	      const result = await handleListRepos(ledgerRoot);
133	      expect(result[0]!.has_vision).toBe(false);
134	    });
135	  });
136	
137	  // ─── handleGetRepo ───────────────────────────────────────────────────────
138	
139	  describe('handleGetRepo (GET /api/repos/:repoId)', () => {
140	    it('AC-5: returns the full entry for an existing repoId', async () => {
141	      const created = await handleCreateRepo(
142	        ledgerRoot,
143	        makeCreateBody({ id: 'target-repo', label: 'Target', folder_names: ['target-folder'] })
144	      );
145	
146	      const result = await handleGetRepo(ledgerRoot, 'target-repo');
147	      expect(result).toEqual(created);
148	    });
149	
150	    it('AC-5: returns 404 when the repoId does not exist', async () => {
151	      await expect(handleGetRepo(ledgerRoot, 'nonexistent')).rejects.toMatchObject({
152	        code: 'NOT_FOUND',
153	      });
154	    });
155	
156	    it('AC-5: 404 when registry is empty', async () => {
157	      await expect(handleGetRepo(ledgerRoot, 'any-id')).rejects.toMatchObject({
158	        code: 'NOT_FOUND',
159	      });
160	    });
161	
162	    it('AC-5: returns the correct entry when multiple exist', async () => {
163	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'alpha', label: 'Alpha', folder_names: ['fa'] }));
164	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'beta', label: 'Beta', folder_names: ['fb'] }));
165	
166	      const result = await handleGetRepo(ledgerRoot, 'beta');
167	      expect(result.id).toBe('beta');
168	      expect(result.label).toBe('Beta');
169	    });
170	  });
171	
172	  // ─── handleCreateRepo ────────────────────────────────────────────────────
173	
174	  describe('handleCreateRepo (POST /api/repos)', () => {
175	    it('AC-2: creates a new entry and persists it to the registry', async () => {
176	      const result = await handleCreateRepo(
177	        ledgerRoot,
178	        makeCreateBody({ id: 'new-repo', label: 'New Repo', folder_names: ['new-folder'] })
179	      );
180	
181	      expect(result.id).toBe('new-repo');
182	      expect(result.label).toBe('New Repo');
183	      expect(result.folder_names).toEqual(['new-folder']);
184	      expect(result.created_at).toBeTruthy();
185	      expect(result.last_modified).toBeTruthy();
186	
187	      // Verify persistence
188	      const registry = await loadRegistry(ledgerRoot);
189	      expect(registry.repositories).toHaveLength(1);
190	      expect(registry.repositories[0]!.id).toBe('new-repo');
191	    });
192	
193	    it('AC-2: defaults vision to all-null when not provided', async () => {
194	      const result = await handleCreateRepo(ledgerRoot, makeCreateBody());
195	      expect(result.vision).toEqual({ short_term: null, mid_term: null, long_term: null });
196	    });
197	
198	    it('AC-2: persists explicit vision when provided', async () => {
199	      const result = await handleCreateRepo(
200	        ledgerRoot,
201	        makeCreateBody({
202	          vision: { short_term: 'Short', mid_term: 'Mid', long_term: 'Long' },
203	        })
204	      );
205	      expect(result.vision).toEqual({
206	        short_term: 'Short',
207	        mid_term: 'Mid',
208	        long_term: 'Long',
209	      });
210	    });
211	
212	    it('AC-2: rejects id that does not match SLUG_REGEX', async () => {
213	      await expect(
214	        handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'invalid id!' }))
215	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
216	    });
217	
218	    it('AC-2: rejects id starting with a hyphen', async () => {
219	      await expect(
220	        handleCreateRepo(ledgerRoot, makeCreateBody({ id: '-bad-start' }))
221	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
222	    });
223	
224	    it('AC-2: accepts id with underscores and hyphens', async () => {
225	      const result = await handleCreateRepo(
226	        ledgerRoot,
227	        makeCreateBody({ id: 'my_repo-123', folder_names: ['mf'] })
228	      );
229	      expect(result.id).toBe('my_repo-123');
230	    });
231	
232	    it('AC-2: rejects duplicate id', async () => {
233	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'dup-repo', folder_names: ['f1'] }));
234	      await expect(
235	        handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'dup-repo', folder_names: ['f2'] }))
236	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
237	    });
238	
239	    it('AC-2: error message is clear on duplicate id', async () => {
240	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'dup-repo', folder_names: ['f1'] }));
241	      const err = await handleCreateRepo(
242	        ledgerRoot,
243	        makeCreateBody({ id: 'dup-repo', folder_names: ['f2'] })
244	      ).catch((e) => e as ApiError);
245	      expect(err.message).toContain("'dup-repo'");
246	      expect(err.message).toContain('already exists');
247	    });
248	
249	    it('AC-2: rejects empty label', async () => {
250	      await expect(
251	        handleCreateRepo(ledgerRoot, makeCreateBody({ label: '' }))
252	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
253	    });
254	
255	    it('AC-2: rejects empty folder_names array', async () => {
256	      await expect(
257	        handleCreateRepo(ledgerRoot, { id: 'r', label: 'L', folder_names: [] })
258	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
259	    });
260	
261	    it('AC-2: rejects unknown fields in body (strict schema)', async () => {
262	      await expect(
263	        handleCreateRepo(ledgerRoot, { ...makeCreateBody(), extra_field: true })
264	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
265	    });
266	
267	    it('AC-2: rejects non-object body', async () => {
268	      await expect(handleCreateRepo(ledgerRoot, null)).rejects.toMatchObject({
269	        code: 'VALIDATION_ERROR',
270	      });
271	    });
272	
273	    // AC-6: Folder name uniqueness
274	    it('AC-6: rejects folder_name that conflicts with an existing entry', async () => {
275	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', folder_names: ['shared-folder'] }));
276	      await expect(
277	        handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-b', folder_names: ['shared-folder'] }))
278	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
279	    });
280	
281	    it('AC-6: error message names the conflicting folder_name', async () => {
282	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', folder_names: ['clash'] }));
283	      const err = await handleCreateRepo(
284	        ledgerRoot,
285	        makeCreateBody({ id: 'repo-b', folder_names: ['clash'] })
286	      ).catch((e) => e as ApiError);
287	      expect(err.message).toContain("'clash'");
288	    });
289	
290	    it('AC-6: detects conflict in multi-item folder_names', async () => {
291	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', folder_names: ['used-folder'] }));
292	      await expect(
293	        handleCreateRepo(
294	          ledgerRoot,
295	          makeCreateBody({ id: 'repo-b', folder_names: ['new-folder', 'used-folder'] })
296	        )
297	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
298	    });
299	
300	    it('allows multiple folder_names within one entry', async () => {
301	      const result = await handleCreateRepo(
302	        ledgerRoot,
303	        makeCreateBody({ folder_names: ['folder-one', 'folder-two', 'folder-three'] })
304	      );
305	      expect(result.folder_names).toEqual(['folder-one', 'folder-two', 'folder-three']);
306	    });
307	  });
308	
309	  // ─── handleUpdateRepo ────────────────────────────────────────────────────
310	
311	  describe('handleUpdateRepo (PUT /api/repos/:repoId)', () => {
312	    let created: RepositoryEntry;
313	
314	    beforeEach(async () => {
315	      created = await handleCreateRepo(
316	        ledgerRoot,
317	        makeCreateBody({ id: 'base-repo', label: 'Base', folder_names: ['base-folder'] })
318	      );
319	    });
320	
321	    it('AC-3: updates label when supplied', async () => {
322	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', { label: 'Updated Label' });
323	      expect(result.label).toBe('Updated Label');
324	      expect(result.id).toBe('base-repo');
325	      expect(result.folder_names).toEqual(['base-folder']);
326	    });
327	
328	    it('AC-3: updates folder_names when supplied', async () => {
329	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', {
330	        folder_names: ['new-folder', 'alias-folder'],
331	      });
332	      expect(result.folder_names).toEqual(['new-folder', 'alias-folder']);
333	    });
334	
335	    it('AC-3: updates vision when supplied', async () => {
336	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', {
337	        vision: { short_term: 'S', mid_term: 'M', long_term: 'L' },
338	      });
339	      expect(result.vision).toEqual({ short_term: 'S', mid_term: 'M', long_term: 'L' });
340	    });
341	
342	    it('AC-3: updates all three mutable fields at once', async () => {
343	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', {
344	        label: 'All Updated',
345	        folder_names: ['updated-folder'],
346	        vision: { short_term: 'Short', mid_term: null, long_term: null },
347	      });
348	      expect(result.label).toBe('All Updated');
349	      expect(result.folder_names).toEqual(['updated-folder']);
350	      expect(result.vision.short_term).toBe('Short');
351	    });
352	
353	    it('AC-3: preserves unchanged fields when only one field is updated', async () => {
354	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', { label: 'New Name' });
355	      expect(result.folder_names).toEqual(created.folder_names);
356	      expect(result.vision).toEqual(created.vision);
357	    });
358	
359	    it('AC-3: sets last_modified on update', async () => {
360	      // Introduce a brief delay so last_modified can differ from created_at
361	      await new Promise((r) => setTimeout(r, 5));
362	      const result = await handleUpdateRepo(ledgerRoot, 'base-repo', { label: 'Updated' });
363	      expect(result.created_at).toBe(created.created_at);
364	      // last_modified should be a valid ISO string (may equal created_at in fast tests)
365	      expect(typeof result.last_modified).toBe('string');
366	    });
367	
368	    it('AC-3: update is persisted to the registry file', async () => {
369	      await handleUpdateRepo(ledgerRoot, 'base-repo', { label: 'Persisted Label' });
370	      const registry = await loadRegistry(ledgerRoot);
371	      const found = registry.repositories.find((e) => e.id === 'base-repo');
372	      expect(found?.label).toBe('Persisted Label');
373	    });
374	
375	    it('AC-3: throws NOT_FOUND for unknown repoId', async () => {
376	      await expect(
377	        handleUpdateRepo(ledgerRoot, 'ghost-repo', { label: 'X' })
378	      ).rejects.toMatchObject({ code: 'NOT_FOUND' });
379	    });
380	
381	    it('AC-3: rejects empty label', async () => {
382	      await expect(
383	        handleUpdateRepo(ledgerRoot, 'base-repo', { label: '' })
384	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
385	    });
386	
387	    it('AC-3: rejects empty folder_names array', async () => {
388	      await expect(
389	        handleUpdateRepo(ledgerRoot, 'base-repo', { folder_names: [] })
390	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
391	    });
392	
393	    it('AC-3: rejects unknown fields in body', async () => {
394	      await expect(
395	        handleUpdateRepo(ledgerRoot, 'base-repo', { label: 'X', id: 'new-id' })
396	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
397	    });
398	
399	    // AC-6: folder_name uniqueness on update
400	    it('AC-6: rejects folder_names that conflict with a different entry', async () => {

401	      await handleCreateRepo(
402	        ledgerRoot,
403	        makeCreateBody({ id: 'other-repo', label: 'Other', folder_names: ['other-folder'] })
404	      );
405	      await expect(
406	        handleUpdateRepo(ledgerRoot, 'base-repo', { folder_names: ['other-folder'] })
407	      ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
408	    });
